import * as childProcess from 'child_process';
import fs from 'fs';
import os from 'os';
import path from 'path';
import { selectedOperatingSystemServices } from '../services/OperatingSystemServices';
import {
  claudeDesktopConfigPath,
  cursorMcpConfigPath,
  isServeRegistration,
} from './legacyMcp';
import { errorMessage } from '../utils/errorMessage';
import { subprocessEnvironment } from '../utils/subprocessEnvironment';

export { isServeRegistration };

export const MCP_SERVER_NAME = 'rivet';

export type McpRegistrationResult = {
  ok: boolean;
  changed: boolean;
  error?: string;
};

export type McpServeVerificationResult = {
  ok: boolean;
  error?: string;
};

const MCP_SERVE_VERIFICATION_TIMEOUT_MS = 10_000;

const RESOLVED_RIVET_BIN = path.resolve(
  __dirname,
  '..',
  '..',
  'bin',
  'rivet.js',
);

export const isEphemeralNpxInstall = (
  binPath: string = RESOLVED_RIVET_BIN,
): boolean => binPath.split(path.sep).includes('_npx');

export const rivetMcpInvocation = (
  callerAgent?: 'claude' | 'codex' | 'cursor',
  overrides?: { binPath?: string },
): { command: string; args: string[]; durable: boolean } => {
  const binPath = overrides?.binPath ?? RESOLVED_RIVET_BIN;
  return {
    command: process.execPath,
    args: [
      binPath,
      'mcp',
      'serve',
      ...(callerAgent ? ['--caller-agent', callerAgent] : []),
    ],
    durable: !isEphemeralNpxInstall(binPath),
  };
};

export const verifyMcpServeInvocation = (
  spawnSync: typeof childProcess.spawnSync = childProcess.spawnSync,
): McpServeVerificationResult => {
  const invocation = rivetMcpInvocation();
  const input = [
    {
      jsonrpc: '2.0',
      id: 1,
      method: 'initialize',
      params: {
        protocolVersion: '2025-06-18',
        capabilities: {},
        clientInfo: { name: 'rivet-install', version: '1' },
      },
    },
    { jsonrpc: '2.0', method: 'notifications/initialized' },
    { jsonrpc: '2.0', id: 2, method: 'tools/list', params: {} },
  ]
    .map((message) => JSON.stringify(message))
    .join('\n');
  const result = spawnSync(invocation.command, invocation.args, {
    encoding: 'utf8',
    env: {
      ...subprocessEnvironment('rivetRuntime'),
      RIVET_LOG_LEVEL: 'SILENT',
      RIVET_AUTO_UPDATE_DISABLED: '1',
    },
    input: `${input}\n`,
    timeout: MCP_SERVE_VERIFICATION_TIMEOUT_MS,
  });
  const stderr = String(result.stderr ?? '').trim();
  if (result.error) {
    return { ok: false, error: result.error.message };
  }
  if (result.status !== 0) {
    return {
      ok: false,
      error: `MCP server exited ${result.status ?? 'without a status'}${
        stderr ? `: ${stderr}` : ''
      }`,
    };
  }
  const messages = String(result.stdout ?? '')
    .split(/\r?\n/)
    .filter(Boolean)
    .flatMap((line): unknown[] => {
      try {
        return [JSON.parse(line)];
      } catch {
        return [];
      }
    });
  const initializeResponse = messages.find(
    (message) =>
      typeof message === 'object' &&
      message !== null &&
      (message as { id?: unknown }).id === 1,
  ) as { result?: { serverInfo?: { name?: string } } } | undefined;
  const toolsResponse = messages.find(
    (message) =>
      typeof message === 'object' &&
      message !== null &&
      (message as { id?: unknown }).id === 2,
  ) as { result?: { tools?: Array<{ name?: string }> } } | undefined;
  if (initializeResponse?.result?.serverInfo?.name !== MCP_SERVER_NAME) {
    return { ok: false, error: 'MCP server did not initialize as Rivet' };
  }
  if (
    !toolsResponse?.result?.tools?.some(
      (tool) => tool.name === 'rivet_get_exploration',
    )
  ) {
    return { ok: false, error: 'MCP server did not expose Rivet tools' };
  }
  return { ok: true };
};

const EPHEMERAL_REGISTRATION_ERROR =
  "Rivet is running from npm's ephemeral npx cache, so any registration " +
  'would break on the next cache prune. Install Rivet globally first ' +
  '(npm install -g rivet-design), then re-run the install.';

const writeMcpServersEntry = (
  configPath: string,
  callerAgent?: 'claude' | 'codex' | 'cursor',
): McpRegistrationResult => {
  let config: { mcpServers?: Record<string, unknown> } = {};
  if (fs.existsSync(configPath)) {
    try {
      const parsed = JSON.parse(fs.readFileSync(configPath, 'utf8'));
      if (
        parsed === null ||
        typeof parsed !== 'object' ||
        Array.isArray(parsed)
      ) {
        return {
          ok: false,
          changed: false,
          error: 'config is not a JSON object',
        };
      }
      config = parsed;
    } catch {
      return { ok: false, changed: false, error: 'config is not valid JSON' };
    }
  }
  const invocation = rivetMcpInvocation(callerAgent);
  if (!invocation.durable) {
    return { ok: false, changed: false, error: EPHEMERAL_REGISTRATION_ERROR };
  }
  const existing = config.mcpServers?.[MCP_SERVER_NAME];
  const desired = { command: invocation.command, args: invocation.args };
  if (existing && JSON.stringify(existing) === JSON.stringify(desired)) {
    return { ok: true, changed: false };
  }
  config.mcpServers = { ...config.mcpServers, [MCP_SERVER_NAME]: desired };
  try {
    fs.mkdirSync(path.dirname(configPath), { recursive: true });
    fs.writeFileSync(
      configPath,
      JSON.stringify(config, null, 2) + '\n',
      'utf8',
    );
    return { ok: true, changed: true };
  } catch (error) {
    return {
      ok: false,
      changed: false,
      error: errorMessage(error),
    };
  }
};

const removeMcpServersEntry = (configPath: string): McpRegistrationResult => {
  if (!fs.existsSync(configPath)) return { ok: true, changed: false };
  let config: { mcpServers?: Record<string, unknown> };
  try {
    config = JSON.parse(fs.readFileSync(configPath, 'utf8'));
  } catch {
    return { ok: false, changed: false, error: 'config is not valid JSON' };
  }
  if (!config?.mcpServers || !(MCP_SERVER_NAME in config.mcpServers)) {
    return { ok: true, changed: false };
  }
  delete config.mcpServers[MCP_SERVER_NAME];
  fs.writeFileSync(configPath, JSON.stringify(config, null, 2) + '\n', 'utf8');
  return { ok: true, changed: true };
};

const hasServeRegistrationInConfig = (configPath: string): boolean => {
  try {
    const parsed = JSON.parse(fs.readFileSync(configPath, 'utf8')) as {
      mcpServers?: Record<string, unknown>;
    };
    return isServeRegistration(parsed?.mcpServers?.[MCP_SERVER_NAME]);
  } catch {
    return false;
  }
};

const hasRivetRegistrationInConfig = (configPath: string): boolean => {
  try {
    const parsed = JSON.parse(fs.readFileSync(configPath, 'utf8')) as {
      mcpServers?: Record<string, unknown>;
    };
    return Boolean(
      parsed?.mcpServers &&
      (MCP_SERVER_NAME in parsed.mcpServers ||
        'rivet-local' in parsed.mcpServers),
    );
  } catch {
    return false;
  }
};

export const registerClaudeDesktopMcp = (
  homeDir: string = os.homedir(),
): McpRegistrationResult =>
  writeMcpServersEntry(claudeDesktopConfigPath(homeDir));

export const hasClaudeDesktopServeRegistration = (
  homeDir: string = os.homedir(),
): boolean => hasServeRegistrationInConfig(claudeDesktopConfigPath(homeDir));

export const hasClaudeDesktopRivetRegistration = (
  homeDir: string = os.homedir(),
): boolean => hasRivetRegistrationInConfig(claudeDesktopConfigPath(homeDir));

export const hasCursorServeRegistration = (
  homeDir: string = os.homedir(),
): boolean => hasServeRegistrationInConfig(cursorMcpConfigPath(homeDir));

export const hasCursorRivetRegistration = (
  homeDir: string = os.homedir(),
): boolean => hasRivetRegistrationInConfig(cursorMcpConfigPath(homeDir));

export const unregisterClaudeDesktopMcp = (
  homeDir: string = os.homedir(),
): McpRegistrationResult =>
  removeMcpServersEntry(claudeDesktopConfigPath(homeDir));

export const registerCursorMcp = (
  homeDir: string = os.homedir(),
): McpRegistrationResult =>
  writeMcpServersEntry(cursorMcpConfigPath(homeDir), 'cursor');

export const unregisterCursorMcp = (
  homeDir: string = os.homedir(),
): McpRegistrationResult => removeMcpServersEntry(cursorMcpConfigPath(homeDir));

export type HostCommandExecutor = (
  bin: string,
  args: string[],
  options: { stdio: 'ignore' | 'pipe' },
) => string | Buffer;

export const executeHostCommandSync: HostCommandExecutor = (
  bin,
  args,
  options,
) =>
  selectedOperatingSystemServices.hostCommands.executeSync(
    { executable: bin, args },
    options,
  );

const registerViaHostCli = (
  bin: string,
  removeArgs: string[],
  addArgs: string[],
  executeHostCommand: HostCommandExecutor,
  callerAgent?: 'claude' | 'codex' | 'cursor',
): McpRegistrationResult => {
  const invocation = rivetMcpInvocation(callerAgent);
  if (!invocation.durable) {
    return { ok: false, changed: false, error: EPHEMERAL_REGISTRATION_ERROR };
  }
  try {
    executeHostCommand(bin, removeArgs, { stdio: 'pipe' });
  } catch {}
  try {
    executeHostCommand(
      bin,
      [
        ...addArgs,
        MCP_SERVER_NAME,
        '--',
        invocation.command,
        ...invocation.args,
      ],
      { stdio: 'pipe' },
    );
    return { ok: true, changed: true };
  } catch (error) {
    return {
      ok: false,
      changed: false,
      error: errorMessage(error),
    };
  }
};

export const hasServeRegistrationViaHostCli = (
  bin: string,
  executeHostCommand: HostCommandExecutor = executeHostCommandSync,
): boolean => {
  try {
    const output = executeHostCommand(bin, ['mcp', 'get', MCP_SERVER_NAME], {
      stdio: 'pipe',
    }).toString();
    return /mcp serve/.test(output);
  } catch {
    return false;
  }
};

export const hasRivetRegistrationViaHostCli = (
  bin: string,
  executeHostCommand: HostCommandExecutor = executeHostCommandSync,
): boolean => {
  try {
    executeHostCommand(bin, ['mcp', 'get', MCP_SERVER_NAME], { stdio: 'pipe' });
    return true;
  } catch {
    return false;
  }
};

export const registerClaudeCodeMcp = (
  executeHostCommand: HostCommandExecutor = executeHostCommandSync,
  bin: string = 'claude',
): McpRegistrationResult =>
  registerViaHostCli(
    bin,
    ['mcp', 'remove', MCP_SERVER_NAME],
    ['mcp', 'add', '--scope', 'user'],
    executeHostCommand,
    'claude',
  );

export const unregisterClaudeCodeMcp = (
  executeHostCommand: HostCommandExecutor = executeHostCommandSync,
  bin: string = 'claude',
): McpRegistrationResult => {
  try {
    executeHostCommand(bin, ['mcp', 'remove', MCP_SERVER_NAME], {
      stdio: 'pipe',
    });
    return { ok: true, changed: true };
  } catch {
    return { ok: true, changed: false };
  }
};

export const registerCodexMcp = (
  executeHostCommand: HostCommandExecutor = executeHostCommandSync,
): McpRegistrationResult =>
  registerViaHostCli(
    'codex',
    ['mcp', 'remove', MCP_SERVER_NAME],
    ['mcp', 'add'],
    executeHostCommand,
    'codex',
  );

export const unregisterCodexMcp = (
  executeHostCommand: HostCommandExecutor = executeHostCommandSync,
): McpRegistrationResult => {
  try {
    executeHostCommand('codex', ['mcp', 'remove', MCP_SERVER_NAME], {
      stdio: 'pipe',
    });
    return { ok: true, changed: true };
  } catch {
    return { ok: true, changed: false };
  }
};
